if(!customElements.get("mp4-video")){class t extends HTMLElement{constructor(){super(),this.video=this.querySelector(".media-video"),this.pauseBtn=this.querySelector(".pause-button"),this.playBtn=this.querySelector(".play-button"),this.muteBtn=this.querySelector(".mute-video"),this.playBtn&&this.playBtn.addEventListener("click",()=>this.videoPlay()),this.pauseBtn&&this.pauseBtn.addEventListener("click",()=>this.videoPause()),this.muteBtn&&this.muteBtn.addEventListener("click",()=>this.videoMute()),(this.pauseBtn||this.playBtn)&&this.video.addEventListener("click",t=>this.checkVideoState(t))}checkVideoState(t){t.preventDefault(),this.video.paused?this.videoPlay():this.videoPause()}videoPlay(){this.video.play(),this.playBtn&&this.playBtn.classList.add("hidden"),this.pauseBtn&&this.pauseBtn.classList.remove("hidden")}videoPause(){this.video.pause(),this.playBtn&&this.playBtn.classList.remove("hidden"),this.pauseBtn&&this.pauseBtn.classList.add("hidden")}videoMute(){this.video.hasAttribute("muted")?this.video.removeAttribute("muted"):this.video.setAttribute("muted",""),this.muteBtn&&this.muteBtn.classList.toggle("unmute-video")}}customElements.define("mp4-video",t)}